import { useCallback, useEffect, useRef, useState } from "react";

type DragModifierKey = "Cmd" | "Shift" | "Alt";

/** Subset of any keyboard/mouse event carrying the modifier flags we read. */
type ModifierState = { metaKey: boolean; ctrlKey: boolean; shiftKey: boolean; altKey: boolean };

type UseDragScrollOptions = {
  disabled?: boolean;
  /** When set, drag-scroll only engages while this key is held (absent = always on). */
  enableModifierKey?: DragModifierKey;
  /** Legacy: drag-scroll is skipped while this key is held. */
  disableModifierKey?: DragModifierKey;
};

// Resolved once on the client. "Cmd" means the platform's primary command key — ⌘ on Apple,
// Ctrl elsewhere — so callers stay platform-agnostic and the branch lives here, not at each usage.
// (Ctrl is deliberately NOT accepted on Apple: Ctrl+mousedown there is a secondary-click.)
const IS_APPLE_PLATFORM =
  typeof navigator !== "undefined" &&
  /Mac|iPhone|iPad|iPod/i.test(
    (navigator as Navigator & { userAgentData?: { platform?: string } }).userAgentData?.platform ??
      navigator.platform ??
      navigator.userAgent
  );

/** Reads whether a configured modifier key is currently down on any keyboard/mouse event. */
const isModifierKeyDown = (key: DragModifierKey, mods: ModifierState) => {
  switch (key) {
    case "Cmd":
      return IS_APPLE_PLATFORM ? mods.metaKey : mods.ctrlKey;
    case "Shift":
      return mods.shiftKey;
    case "Alt":
      return mods.altKey;
  }
};

type UseDragScrollResult<T> = {
  eventHandlers: {
    onMouseDown: (e: React.MouseEvent) => void;
    onTouchStart: (e: React.TouchEvent) => void;
    ref: React.RefObject<T | null>;
  };
  isDragScrollEnabled: boolean;
  isDragging: boolean;
  isOverflowing: boolean;
  isSkip: boolean;
};

export function useDragScroll<T extends HTMLElement>(options: UseDragScrollOptions = {}): UseDragScrollResult<T> {
  const { disabled = false, enableModifierKey, disableModifierKey } = options;

  const ref = useRef<T>(null);
  const isDraggingRef = useRef(false);
  const startX = useRef(0);
  const startY = useRef(0);
  const scrollLeft = useRef(0);
  const scrollTop = useRef(0);
  const rafId = useRef<number | null>(null);
  const delta = useRef<{ x: number; y: number }>({ x: 0, y: 0 });

  const [isDragging, setIsDragging] = useState(false);
  const [isOverflowing, setIsOverflowing] = useState(false);
  const [isSkip, setIsSkip] = useState(false);

  const usesModifierKey = Boolean(enableModifierKey || disableModifierKey);

  // Given the modifiers held on an event, decide whether dragging is currently permitted.
  const computeModifierAllows = useCallback(
    (mods: ModifierState) => {
      if (enableModifierKey && !isModifierKeyDown(enableModifierKey, mods)) return false;
      if (disableModifierKey && isModifierKeyDown(disableModifierKey, mods)) return false;
      return true;
    },
    [enableModifierKey, disableModifierKey]
  );

  // Reactive mirror of computeModifierAllows for the *currently* held keys, so cursor css and
  // helper messages can respond to key presses without waiting for a mouse event. Stays true and
  // untouched when no modifier key is configured, so the common (table) case costs nothing.
  const [modifierAllowsDrag, setModifierAllowsDrag] = useState(() => !enableModifierKey);

  useEffect(() => {
    if (!usesModifierKey) return;
    const sync = (e: KeyboardEvent) => setModifierAllowsDrag(computeModifierAllows(e));
    // Key-up can be missed when focus leaves the window mid-press; reset to the no-keys state.
    const reset = () =>
      setModifierAllowsDrag(computeModifierAllows({ metaKey: false, ctrlKey: false, shiftKey: false, altKey: false }));
    document.addEventListener("keydown", sync);
    document.addEventListener("keyup", sync);
    window.addEventListener("blur", reset);
    return () => {
      document.removeEventListener("keydown", sync);
      document.removeEventListener("keyup", sync);
      window.removeEventListener("blur", reset);
    };
  }, [usesModifierKey, computeModifierAllows]);

  const updateOverflow = useCallback(() => {
    if (ref.current) {
      const el = ref.current;
      setIsOverflowing(el.scrollWidth > el.clientWidth || el.scrollHeight > el.clientHeight);
    }
  }, []);

  useEffect(() => {
    updateOverflow();
    const observer = new ResizeObserver(updateOverflow);
    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, [updateOverflow]);

  const doScroll = useCallback(() => {
    if (!ref.current) return;
    const el = ref.current;
    el.scrollLeft = scrollLeft.current - delta.current.x;
    el.scrollTop = scrollTop.current - delta.current.y;
    rafId.current = null;
  }, []);

  const scheduleScroll = useCallback(() => {
    if (rafId.current == null) {
      rafId.current = requestAnimationFrame(doScroll);
    }
  }, [doScroll]);

  const onMouseDown = useCallback(
    (e: React.MouseEvent) => {
      // enableModifierKey: must be held to drag. disableModifierKey (legacy): must NOT be held.
      if (usesModifierKey && !computeModifierAllows(e)) {
        setIsSkip(true);
        setIsDragging(false);
        return;
      }
      setIsSkip(false);

      if (disabled || !ref.current) return;
      // Only work if the current el ref has the mouse
      if (!ref.current.contains(e.target as Node)) return;

      isDraggingRef.current = true;
      setIsDragging(true);
      startX.current = e.pageX - ref.current.offsetLeft;
      startY.current = e.pageY - ref.current.offsetTop;
      scrollLeft.current = ref.current.scrollLeft;
      scrollTop.current = ref.current.scrollTop;

      const onMouseMove = (ev: MouseEvent) => {
        if (!isDraggingRef.current || !ref.current) return;
        delta.current.x = ev.pageX - ref.current.offsetLeft - startX.current;
        delta.current.y = ev.pageY - ref.current.offsetTop - startY.current;
        scheduleScroll();
      };

      const onMouseUp = () => {
        isDraggingRef.current = false;
        setIsDragging(false);
        document.removeEventListener("mousemove", onMouseMove);
        document.removeEventListener("mouseup", onMouseUp);
      };

      document.addEventListener("mousemove", onMouseMove, { passive: true });
      document.addEventListener("mouseup", onMouseUp, { passive: true });
    },
    [disabled, scheduleScroll, usesModifierKey, computeModifierAllows]
  );

  const onTouchStart = useCallback(
    (e: React.TouchEvent) => {
      if (disabled || !ref.current) return;
      isDraggingRef.current = true;
      setIsDragging(true);
      startX.current = e.touches[0].pageX - ref.current.offsetLeft;
      startY.current = e.touches[0].pageY - ref.current.offsetTop;
      scrollLeft.current = ref.current.scrollLeft;
      scrollTop.current = ref.current.scrollTop;

      const onTouchMove = (ev: TouchEvent) => {
        if (!isDraggingRef.current || !ref.current) return;
        delta.current.x = ev.touches[0].pageX - ref.current.offsetLeft - startX.current;
        delta.current.y = ev.touches[0].pageY - ref.current.offsetTop - startY.current;
        scheduleScroll();
      };

      const onTouchEnd = () => {
        isDraggingRef.current = false;
        setIsDragging(false);
        document.removeEventListener("touchmove", onTouchMove);
        document.removeEventListener("touchend", onTouchEnd);
      };

      document.addEventListener("touchmove", onTouchMove, { passive: true });
      document.addEventListener("touchend", onTouchEnd, { passive: true });
    },
    [disabled, scheduleScroll]
  );

  const isDragScrollEnabled = !disabled && modifierAllowsDrag;

  return {
    eventHandlers: { onMouseDown, onTouchStart, ref },
    isDragging,
    isOverflowing,
    isSkip,
    isDragScrollEnabled,
  };
}

